type scsSession struct{tx *gorm.DB;l *dbFlowLoader;rec *scpRecorder;c scpControls;setupPath,setupHash string;start time.Time;requests int}
func scsNewSession(db *gorm.DB,rec *scpRecorder,dir string,n int)(session *scsSession,retErr error){
 tx:=db.Begin(&sql.TxOptions{Isolation:sql.LevelRepeatableRead,ReadOnly:true});if tx.Error!=nil{return nil,tx.Error};defer func(){if retErr!=nil{tx.Rollback()}}();rec.Phase="snapshot_session_controls"
 for _,q:=range []string{"SET LOCAL statement_timeout='180s'","SET LOCAL lock_timeout='2s'","SET LOCAL max_parallel_workers_per_gather=0","SET LOCAL synchronize_seqscans=off"}{if e:=tx.Exec(q).Error;e!=nil{return nil,e}}
 rec.Phase="initial_snapshot_controls";c,e:=scpReadControls(tx);if e!=nil{return nil,e};queryStart:=len(rec.Queries);s:=&Server{db:tx,readOnlyLedger:true};rec.Phase="all_validators_once";validators,e:=s.commissionValidators(apiMainnet);if e!=nil{return nil,e};rec.Phase="stored_labels_once";var labels []AddressLabel;if e=tx.Where("chain = ?",apiMainnet).Find(&labels).Error;e!=nil{return nil,e};derived:=derivedFlowLabels(apiMainnet,validators)
 l:=&dbFlowLoader{s:s,chain:apiMainnet,private:true,labels:map[string]AddressLabel{},mu:&sync.Mutex{},chans:map[string]string{}};for _,x:=range labels{l.labels[x.Address]=x};for _,x:=range derived{if _,ok:=l.labels[x.Address];!ok{l.labels[x.Address]=x}}
 rec.Phase="setup_settings";var settings []struct{Name string;Setting string};if e=tx.Raw("SELECT name, setting FROM pg_settings WHERE name IN ('max_parallel_workers_per_gather','synchronize_seqscans','plan_cache_mode','idle_in_transaction_session_timeout','transaction_read_only','default_transaction_read_only') ORDER BY name").Scan(&settings).Error;e!=nil{return nil,e};after,e:=scpReadControls(tx);if e!=nil||after!=c{return nil,fmt.Errorf("setup transaction identity changed")}
 for _,q:=range rec.Queries[queryStart:]{if !q.EOF||!q.Closed||q.Error!=""{return nil,fmt.Errorf("incomplete setup actual rows")}}
 p:=map[string]any{"source":scpSource,"controls":c,"all_commission_validators":validators,"stored_labels":labels,"derived_labels":derived,"queries":rec.Queries[queryStart:],"settings":settings,"snapshot_scope":"one persistent repeatable-read readonly transaction, initialized once per loader; maximum10minutes or1000requests then rollback and fresh initialization","financially_accepted":false};for _,name:=range []string{"commissionflows.go","balancedays.go","zz_ops818_stop_cache_probe_test.go","zz_ops818_stop_cache_verify_test.go","zz_ops818_stop_shared_supplier_test.go"}{b,e:=os.ReadFile(filepath.Join("/Users/danb/code/worktrees/cosmos-tax-commission-route-8704/taxapi",name));if e!=nil{return nil,e};p[name+"_sha256"]=scpHash(b)}
 path:=filepath.Join(dir,fmt.Sprintf("snapshot-%04d-label-setup.private.json",n));if e=scpWrite(path,p);e!=nil{return nil,e};b,e:=os.ReadFile(path);if e!=nil{return nil,e};return &scsSession{tx:tx,l:l,rec:rec,c:c,setupPath:path,setupHash:scpHash(b),start:time.Now()},nil
}
func scsAtomicReply(path string,v any)error{b,e:=json.Marshal(v);if e!=nil{return e};temp:=path+fmt.Sprintf(".owned-%d.tmp",os.Getpid());f,e:=os.OpenFile(temp,os.O_CREATE|os.O_EXCL|os.O_WRONLY,0600);if e!=nil{return e};if _,e=f.Write(b);e==nil{e=f.Sync()};ce:=f.Close();if e!=nil{return e};if ce!=nil{return ce};if e=os.Rename(temp,path);e!=nil{return e};dir,e:=os.Open(filepath.Dir(path));if e!=nil{return e};defer dir.Close();return dir.Sync()}
func scsSupply(s *scsSession,root,addr string,request json.RawMessage,dir string,n int)error{
 bindingPath:=filepath.Join(root,"source-evidence.private.json");bindingBytes,e:=os.ReadFile(bindingPath);if e!=nil{return e};var binding map[string]any;if e=json.Unmarshal(bindingBytes,&binding);e!=nil{return e};path,ok:=binding["raw_path"].(string);if !ok{return fmt.Errorf("missing raw path")};rawBytes,e:=os.ReadFile(path);if e!=nil{return e};if binding["source"]!=scpSource||binding["raw_sha256"]!=scpHash(rawBytes){return fmt.Errorf("prior binding invalid")};var raw map[string]any;if e=json.Unmarshal(rawBytes,&raw);e!=nil{return e};if raw["source"]!=scpSource||raw["readonly"]!="on"||raw["assigned_xid"]!=nil{return fmt.Errorf("prior source controls invalid")};channels,ok:=raw["channels"].([]any);if !ok||len(channels)<44{return fmt.Errorf("retained channels missing")};stops,_:=raw["stops"].([]any);for _,v:=range stops{x,ok:=v.(map[string]any);if !ok{return fmt.Errorf("prior stop shape")};if x["address"]==addr{return nil}}
 s.rec.Phase="before_stop_controls";before,e:=scpReadControls(s.tx);if e!=nil||before!=s.c{return fmt.Errorf("before stop transaction identity changed")};start:=time.Now();qstart:=len(s.rec.Queries);wstart:=len(s.rec.Wire);s.rec.Phase="actual_production_stop";stop,e:=s.l.stop(addr);qend:=len(s.rec.Queries);wend:=len(s.rec.Wire);if e!=nil{return e};queries:=s.rec.Queries[qstart:qend];if e=scpVerifyStopRows(addr,s.l,stop,queries);e!=nil{return e};s.rec.Phase="after_stop_controls";after,e:=scpReadControls(s.tx);if e!=nil||after!=s.c{return fmt.Errorf("after stop transaction identity changed")}
 elapsed:=float64(time.Since(start).Microseconds())/1000;proof:=map[string]any{"source":scpSource,"address":addr,"request":request,"stop":stop,"controls":after,"queries":queries,"actual_wire_queries":s.rec.Wire[wstart:wend],"raw_rows_are_actual_classifier_inputs":true,"label_setup_path":s.setupPath,"label_setup_sha256":s.setupHash,"snapshot_age_seconds":time.Since(s.c.TransactionAt).Seconds(),"elapsed_millis":elapsed,"timing_kind":"client-side query send/first-row/EOF-close","audit_requeries":0,"private":true,"readOnlyLedger":true,"financially_accepted":false};b,e:=os.ReadFile("/Users/danb/code/worktrees/cosmos-tax-commission-route-8704/taxapi/commissionflows.go");if e!=nil{return e};proof["commissionflows.go_sha256"]=scpHash(b)
 proofPath:=filepath.Join(dir,fmt.Sprintf("stop-%06d.proof.private.json",n));if e=scpWrite(proofPath,proof);e!=nil{return e};pb,e:=os.ReadFile(proofPath);if e!=nil{return e};raw["stops"]=append(stops,map[string]any{"address":addr,"stop":stop,"proof_path":proofPath,"proof_sha256":scpHash(pb)});refs,_:=raw["external_proofs"].([]any);raw["external_proofs"]=append(refs,map[string]any{"path":path,"sha256":scpHash(rawBytes)},map[string]any{"path":proofPath,"sha256":scpHash(pb)},map[string]any{"path":s.setupPath,"sha256":s.setupHash});raw["readonly"]=after.Readonly;raw["assigned_xid"]=after.AssignedXID;priors,_:=raw["prior_bindings"].([]any);raw["prior_bindings"]=append(priors,map[string]any{"sha256":scpHash(bindingBytes),"binding":binding});rawPath:=filepath.Join(dir,fmt.Sprintf("cumulative-%06d.private.json",n));if e=scpWrite(rawPath,raw);e!=nil{return e};rb,e:=os.ReadFile(rawPath);if e!=nil{return e};current,e:=os.ReadFile(bindingPath);if e!=nil{return e};if !bytes.Equal(current,bindingBytes){return fmt.Errorf("reply changed concurrently")};newBinding:=map[string]any{};for k,v:=range binding{newBinding[k]=v};newBinding["raw_path"]=rawPath;newBinding["raw_sha256"]=scpHash(rb);if e=scsAtomicReply(bindingPath,newBinding);e!=nil{return e};s.requests++;fmt.Printf("phase=shared-stop-supplied count=%d query_count=%d millis=%.3f proof_sha256=%s\n",n,len(queries),elapsed,scpHash(pb));return nil
}
func TestOPS818SharedStopSupplier(t *testing.T){
 dir:=os.Getenv("OPS818_SHARED_STOP_ROOT");if dir==""{t.Skip("owned private only")};syscall.Umask(0077);if e:=os.MkdirAll(dir,0700);e!=nil{t.Fatal("private output failed")};if e:=scpVerifyProduction();e!=nil{t.Fatal(e)};var roots []string;if json.Unmarshal([]byte(os.Getenv("OPS818_SHARED_REQUEST_ROOTS")),&roots)!=nil||len(roots)==0{t.Fatal("explicit owned roots required")};for _,root:=range roots{if root==scpLiveRoot{t.Fatal("original live GATA reply excluded until separate reviewed handover")}}
 rec:=&scpRecorder{Phase:"connect"};cfg,e:=pgx.ParseConfig("host=127.0.0.1 port=15439 user=postgres dbname=cosmostax sslmode=disable application_name=ops818-private-shared-stop-supplier default_transaction_read_only=on");if e!=nil{t.Fatal("config failed")};cfg.Tracer=&scpTracer{rec};pool:=sql.OpenDB(&scpConnector{stdlib.GetConnector(*cfg),rec});defer pool.Close();pool.SetMaxOpenConns(1);db,e:=gorm.Open(postgres.New(postgres.Config{Conn:pool}),&gorm.Config{Logger:logger.Default.LogMode(logger.Silent)});if e!=nil{t.Fatal("source open failed")}
 defer func(){_ = scpWrite(filepath.Join(dir,"terminal-query-evidence.private.json"),map[string]any{"queries":rec.Queries,"wire":rec.Wire})}();snapshotN:=1;s,e:=scsNewSession(db,rec,dir,snapshotN);if e!=nil{_ = scpWrite(filepath.Join(dir,"failure.private.json"),map[string]any{"error":e.Error(),"phase":rec.Phase});t.Fatal("snapshot initialization failed explicitly")};defer func(){s.tx.Rollback()}();count:=0;seen:=map[string]bool{}
 for{var st syscall.Statfs_t;if e=syscall.Statfs(dir,&st);e!=nil||uint64(st.Bavail)*uint64(st.Bsize)<4*1024*1024*1024{t.Fatal("owned reserve stop")};if time.Since(s.c.TransactionAt)>10*time.Minute||s.requests>=1000{s.tx.Rollback();snapshotN++;s,e=scsNewSession(db,rec,dir,snapshotN);if e!=nil{t.Fatal("fresh snapshot failed")}}
 for _,root:=range roots{b,e:=os.ReadFile(filepath.Join(root,"extra-bank-request.private.jsonl"));if os.IsNotExist(e){continue};if e!=nil{t.Fatal("owned journal unavailable")};lines:=bytes.Split(b,[]byte("\n"));for _,line:=range lines[:len(lines)-1]{if len(line)==0{continue};var r struct{Kind string `json:"kind"`;Source string `json:"source"`;Request struct{Address string `json:"address"`} `json:"request"`};if json.Unmarshal(line,&r)!=nil{t.Fatal("request malformed")};if r.Kind!="source-bound-stop"{continue};if r.Source!=scpSource||r.Request.Address==""{t.Fatal("request source guard")};key:=root+"/"+r.Request.Address;if seen[key]{continue};count++;if e=scsSupply(s,root,r.Request.Address,line,dir,count);e!=nil{_ = scpWrite(filepath.Join(dir,"failure.private.json"),map[string]any{"error":e.Error(),"phase":rec.Phase,"count":count});t.Fatal("actual source classification failed explicitly")};seen[key]=true}}
 time.Sleep(time.Second)
 }
}
